-- +goose NO TRANSACTION
-- +goose Up
-- Existing populations belong to the global-only context (''). Dropping
-- sessions with foreign keys enforced would cascade-delete its references, and
-- PRAGMA foreign_keys is a no-op inside goose's transaction, so this runs
-- outside it with enforcement off and its own transaction.
PRAGMA foreign_keys = off;
BEGIN IMMEDIATE;
CREATE TABLE `new_populations` (`project_root` text NOT NULL DEFAULT '', `workflow` text NOT NULL, `name` text NOT NULL, PRIMARY KEY (`project_root`, `workflow`, `name`));
INSERT INTO `new_populations` (`workflow`, `name`) SELECT `workflow`, `name` FROM `populations`;
CREATE TABLE `new_population_members` (`project_root` text NOT NULL DEFAULT '', `workflow` text NOT NULL, `name` text NOT NULL, `resource_id` text NOT NULL, `session_name` text NULL, `generation` integer NOT NULL DEFAULT 0, `accepted_at` text NULL, `last_appearance` text NULL, `last_inbound` text NULL, `tombstoned` boolean NOT NULL DEFAULT 0, `pending_up` boolean NOT NULL DEFAULT 0, `consecutive_admit_failures` integer NOT NULL DEFAULT 0, `last_admit_reason` text NULL, `last_admit_error` text NULL, `admit_retry_at` text NULL, `admit_suspended` boolean NOT NULL DEFAULT 0, `decision_kind` text NULL, `decision_reason` text NULL, `item_json` text NOT NULL DEFAULT '{}', PRIMARY KEY (`project_root`, `workflow`, `name`, `resource_id`), CONSTRAINT `0` FOREIGN KEY (`project_root`, `workflow`, `name`) REFERENCES `populations` (`project_root`, `workflow`, `name`) ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT `1` FOREIGN KEY (`resource_id`) REFERENCES `resources` (`id`) ON UPDATE NO ACTION ON DELETE NO ACTION, CHECK (tombstoned IN (0, 1)), CHECK (pending_up IN (0, 1)), CHECK (admit_suspended IN (0, 1)), CHECK (decision_kind IN ('plect.workflow_population.destroy', 'plect.workflow_population.destroy_deferred', 'plect.workflow_population.destroy_dry_run')), CHECK (json_valid(item_json)));
INSERT INTO `new_population_members` (`workflow`, `name`, `resource_id`, `session_name`, `generation`, `accepted_at`, `last_appearance`, `last_inbound`, `tombstoned`, `pending_up`, `consecutive_admit_failures`, `last_admit_reason`, `last_admit_error`, `admit_retry_at`, `admit_suspended`, `decision_kind`, `decision_reason`, `item_json`) SELECT `workflow`, `name`, `resource_id`, `session_name`, `generation`, `accepted_at`, `last_appearance`, `last_inbound`, `tombstoned`, `pending_up`, `consecutive_admit_failures`, `last_admit_reason`, `last_admit_error`, `admit_retry_at`, `admit_suspended`, `decision_kind`, `decision_reason`, `item_json` FROM `population_members`;
CREATE TABLE `new_population_member_blockers` (`project_root` text NOT NULL DEFAULT '', `workflow` text NOT NULL, `name` text NOT NULL, `resource_id` text NOT NULL, `position` integer NOT NULL, `reason` text NOT NULL, PRIMARY KEY (`project_root`, `workflow`, `name`, `resource_id`, `position`), CONSTRAINT `0` FOREIGN KEY (`project_root`, `workflow`, `name`, `resource_id`) REFERENCES `new_population_members` (`project_root`, `workflow`, `name`, `resource_id`) ON UPDATE NO ACTION ON DELETE CASCADE);
INSERT INTO `new_population_member_blockers` (`workflow`, `name`, `resource_id`, `position`, `reason`) SELECT `workflow`, `name`, `resource_id`, `position`, `reason` FROM `population_member_blockers`;
CREATE TABLE `new_sessions` (`id` text NULL, `name` text NOT NULL, `status` text NOT NULL, `sleep_since` text NULL, `destroyed_at` text NULL, `parent_session_id` text NULL, `root_session_id` text NULL, `resource_id` text NULL REFERENCES `resources` (`id`), `tag` text NULL, `alias` text NULL, `workflow` text NOT NULL, `workflow_revision` text NULL, `project_root` text NOT NULL DEFAULT '', `population_workflow` text NULL, `population_name` text NULL, `inputs_json` text NULL, `health_last_checked_at` text NULL, `health_last_activity_at` text NULL, `health_last_fingerprint` text NULL, `health_last_state` text NULL, `health_last_reason` text NULL, `health_last_notified_at` text NULL, `health_notify_count` integer NULL, `health_unevaluable_cycles` integer NULL, `tick_consecutive_unchanged` integer NULL, `tick_last_fingerprint` text NULL, `last_tick_at` text NULL, `created_at` text NOT NULL, `updated_at` text NOT NULL, PRIMARY KEY (`id`), CONSTRAINT `0` FOREIGN KEY (`project_root`, `population_workflow`, `population_name`) REFERENCES `populations` (`project_root`, `workflow`, `name`) ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT `2` FOREIGN KEY (`root_session_id`) REFERENCES `sessions` (`id`) ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT `3` FOREIGN KEY (`parent_session_id`) REFERENCES `sessions` (`id`) ON UPDATE NO ACTION ON DELETE NO ACTION, CHECK (status IN ('down', 'up', 'destroyed')), CHECK (inputs_json IS NULL OR json_valid(inputs_json)), CHECK (health_last_state IS NULL OR health_last_state IN ('healthy', 'unhealthy', 'stalled', 'undeclared')), CHECK ((status = 'destroyed') = (destroyed_at IS NOT NULL)), CHECK (NOT (parent_session_id IS NOT NULL AND root_session_id IS NOT NULL)), CHECK (root_session_id IS NULL OR root_session_id <> id), CHECK ((population_workflow IS NULL) = (population_name IS NULL)));
INSERT INTO `new_sessions` (`id`, `name`, `status`, `sleep_since`, `destroyed_at`, `parent_session_id`, `root_session_id`, `resource_id`, `tag`, `alias`, `workflow`, `workflow_revision`, `project_root`, `population_workflow`, `population_name`, `inputs_json`, `health_last_checked_at`, `health_last_activity_at`, `health_last_fingerprint`, `health_last_state`, `health_last_reason`, `health_last_notified_at`, `health_notify_count`, `health_unevaluable_cycles`, `tick_consecutive_unchanged`, `tick_last_fingerprint`, `last_tick_at`, `created_at`, `updated_at`) SELECT `id`, `name`, `status`, `sleep_since`, `destroyed_at`, `parent_session_id`, `root_session_id`, `resource_id`, `tag`, `alias`, `workflow`, `workflow_revision`, `project_root`, `population_workflow`, `population_name`, `inputs_json`, `health_last_checked_at`, `health_last_activity_at`, `health_last_fingerprint`, `health_last_state`, `health_last_reason`, `health_last_notified_at`, `health_notify_count`, `health_unevaluable_cycles`, `tick_consecutive_unchanged`, `tick_last_fingerprint`, `last_tick_at`, `created_at`, `updated_at` FROM `sessions`;
DROP TABLE `population_member_blockers`;
DROP TABLE `population_members`;
DROP TABLE `populations`;
DROP TABLE `sessions`;
ALTER TABLE `new_populations` RENAME TO `populations`;
ALTER TABLE `new_population_members` RENAME TO `population_members`;
ALTER TABLE `new_population_member_blockers` RENAME TO `population_member_blockers`;
ALTER TABLE `new_sessions` RENAME TO `sessions`;
CREATE UNIQUE INDEX `sessions_live_name` ON `sessions` (`name`) WHERE status <> 'destroyed';
CREATE INDEX `sessions_alias_idx` ON `sessions` (`alias`);
CREATE INDEX `sessions_parent_idx` ON `sessions` (`parent_session_id`);
CREATE INDEX `sessions_resource_idx` ON `sessions` (`resource_id`);
CREATE INDEX `population_members_resource_idx` ON `population_members` (`resource_id`);
COMMIT;
PRAGMA foreign_keys = on;
